$b='http://localhost:8080';$a='http://localhost:8083';$c="$env:TEMP\prestige-curl-cookies.txt";$r="$env:TEMP\prestige-auth-response.json";$total=0;$passed=0;$failed=0;$expectedFailures=0
function T($n,$e,[string[]]$x){$script:total++;$o=& curl.exe @x 2>$null;$s=(($o|select -Last 1)-as [string]).Trim();if($s -eq $e){$script:passed++;"[PASS] $n (HTTP $s)"}else{$script:failed++;"[FAIL] $n (expected HTTP $e, got $s)"}}
function G($u,$t=''){ $x=@('-sS','-o','NUL','-w','%{http_code}',$u);if($t){$x+=@('-H',"Authorization: Bearer $t")};,$x }
function X($n,[string[]]$x){$script:total++;$o=& curl.exe @x 2>$null;$s=(($o|select -Last 1)-as [string]).Trim();if($s -eq '500'){$script:expectedFailures++;"[XFAIL] $n (HTTP 500: LLM dependency unavailable)"}else{$script:failed++;"[FAIL] $n (expected known HTTP 500 dependency failure, got $s)"}}
'=== Prestige gateway safe test suite ===';'--- Public information service ---';foreach($p in 'home','about-us','contact-us','investors','offers'){T "GET /api/v1/public/$p" 200 (G "$b/api/v1/public/$p")}
'--- Authentication service ---';T 'GET /.well-known/jwks.json' 200 (G "$a/.well-known/jwks.json");$total++;if($env:PRESTIGE_LOGIN_STATUS -eq '200'){$passed++;'[PASS] POST /api/v1/auth/login (HTTP 200)'}else{$failed++;"[FAIL] POST /api/v1/auth/login (expected HTTP 200, got $env:PRESTIGE_LOGIN_STATUS)"};$t=$env:PRESTIGE_TOKEN;if(!$t){$total++;$failed++;'[FAIL] Login response contains accessToken (missing)'}else{
'--- Customer service ---';foreach($p in 'customers/me','accounts','accounts/me','cards','cards?accountNumber=PBS1000003'){T "GET /api/v1/$p" 200 (G "$b/api/v1/$p" $t)}
'--- Transfer service (read-only) ---';foreach($p in 'transfers/REF202600003','accounts/PBS1000003/transactions?movement=WITHDRAWAL&page=0&size=20','accounts/PBS1000003/analytics?months=6'){T "GET /api/v1/$p" 200 (G "$b/api/v1/$p" $t)}
'--- Notification service ---';T 'GET /api/v1/notifications' 200 (G "$b/api/v1/notifications?limit=20" $t);T 'GET /api/v1/notifications/stream (idle SSE timeout)' '000' (@('-sS','-N','--max-time','5','-o','NUL','-w','%{http_code}',"$b/api/v1/notifications/stream",'-H',"Authorization: Bearer $t"))
'--- Chatbot service ---';X 'POST /api/v1/chat' (@('-sS','-o','NUL','-w','%{http_code}','-X','POST',"$b/api/v1/chat",'-H',"Authorization: Bearer $t",'-H','Content-Type: application/json','--data','{"message":"What are your home-loan offers?","conversationId":"curl-smoke-103"}'));X 'POST /api/v1/chat/stream (SSE)' (@('-sS','-N','--max-time','30','-o','NUL','-w','%{http_code}','-X','POST',"$b/api/v1/chat/stream",'-H',"Authorization: Bearer $t",'-H','Content-Type: application/json','--data','{"message":"Summarize the available offers.","conversationId":"curl-smoke-103"}'))
'--- Authentication service: refresh ---';T 'POST /api/v1/auth/refresh' 200 (@('-sS','-b',$c,'-c',$c,'-o','NUL','-w','%{http_code}','-X','POST',"$a/api/v1/auth/refresh"))}
"`n=== Test summary ===";"Total: $total  Passed: $passed  Expected failures: $expectedFailures  Failed: $failed";if($failed){'RESULT: FAIL';exit 1}else{'RESULT: PASS';exit 0}
